import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { mkdir } from "node:fs/promises";
import path from "node:path";

const execFileAsync = promisify(execFile);

const storageRoot = path.resolve(
  process.env.CODEFORGE_STORAGE_PATH || path.join(process.cwd(), ".codeforge", "repositories")
);

// storageKey must be generated by the server (UUID), never supplied by an API caller.
const getRepositoryPath = (storageKey) => {
  if (!/^[0-9a-f]{8}-[0-9a-f-]{27,}$/i.test(storageKey)) {
    throw new Error("Invalid internal repository storage key.");
  }

  const repositoryPath = path.resolve(storageRoot, `${storageKey}.git`);
  if (path.dirname(repositoryPath) !== storageRoot) {
    throw new Error("Repository path escaped the storage root.");
  }

  return repositoryPath;
};

export const initializeBareRepository = async (storageKey) => {
  const repositoryPath = getRepositoryPath(storageKey);
  await mkdir(storageRoot, { recursive: true });

  await execFileAsync("git", [
    "init",
    "--bare",
    "--initial-branch=main",
    repositoryPath,
  ], { timeout: 15_000 });

  return repositoryPath;
};

export const removeBareRepository = async (storageKey) => {
  const repositoryPath = getRepositoryPath(storageKey);

  // Ask Git to validate the target before any future cleanup workflow is added.
  await execFileAsync("git", ["--git-dir", repositoryPath, "rev-parse", "--git-dir"], {
    timeout: 5_000,
  });

  // Physical deletion is intentionally not implemented in this first milestone.
  // Repository deletion needs authenticated authorization and a recoverable retention policy.
  return { repositoryPath, removed: false };
};
